{"path":"/workspace/src/store.js","content":"import { randomUUID } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

export const defaultBooksPath = join(
  dirname(fileURLToPath(import.meta.url)),
  '..',
  'books.json',
);

const LIMITS = {
  title: 200,
  author: 200,
  notes: 5000,
};

export class ValidationError extends Error {
  constructor(errors) {
    super(errors.join(' '));
    this.name = 'ValidationError';
    this.errors = errors;
  }
}

export function validateBook(input = {}) {
  const title = String(input.title ?? '').trim();
  const author = String(input.author ?? '').trim();
  const notes = String(input.notes ?? '').trim();
  const errors = [];

  if (!title) errors.push('Title is required.');
  else if (title.length > LIMITS.title) {
    errors.push(`Title must be ${LIMITS.title} characters or fewer.`);
  }

  if (!author) errors.push('Author is required.');
  else if (author.length > LIMITS.author) {
    errors.push(`Author must be ${LIMITS.author} characters or fewer.`);
  }

  if (notes.length > LIMITS.notes) {
    errors.push(`Notes must be ${LIMITS.notes} characters or fewer.`);
  }

  return {
    ok: errors.length === 0,
    errors,
    value: { title, author, notes },
  };
}

export function groupBooks(books) {
  const reading = [];
  const finished = [];
  for (const book of books) {
    if (book && book.status === 'finished') finished.push(book);
    else if (book) reading.push(book);
  }
  reading.sort((a, b) => String(b.addedAt || '').localeCompare(String(a.addedAt || '')));
  finished.sort((a, b) => String(b.finishedAt || '').localeCompare(String(a.finishedAt || '')));
  return { reading, finished };
}

export function createStore(filePath = defaultBooksPath) {
  let queue = Promise.resolve();

  function enqueue(task) {
    const run = queue.then(task, task);
    queue = run.then(
      () => {},
      () => {},
    );
    return run;
  }

  async function read() {
    let text;
    try {
      text = await readFile(filePath, 'utf8');
    } catch (error) {
      if (error && error.code === 'ENOENT') return [];
      throw error;
    }
    if (text.trim() === '') return [];
    const data = JSON.parse(text);
    if (!Array.isArray(data)) {
      throw new Error(`Expected ${filePath} to contain a JSON array.`);
    }
    return data;
  }

  async function write(books) {
    await mkdir(dirname(filePath), { recursive: true });
    const temporary = `${filePath}.${process.pid}.tmp`;
    await writeFile(temporary, `${JSON.stringify(books, null, 2)}\n`, 'utf8');
    await rename(temporary, filePath);
  }

  return {
    filePath,
    init() {
      return enqueue(async () => {
        try {
          await readFile(filePath, 'utf8');
        } catch (error) {
          if (!error || error.code !== 'ENOENT') throw error;
          await write([]);
        }
      });
    },
    list() {
      return enqueue(read);
    },
    get(id) {
      return enqueue(async () => {
        const books = await read();
        return books.find((book) => book.id === id) ?? null;
      });
    },
    add(input) {
      return enqueue(async () => {
        const result = validateBook(input);
        if (!result.ok) throw new ValidationError(result.errors);
        const books = await read();
        const book = {
          id: randomUUID(),
          title: result.value.title,
          author: result.value.author,
          notes: result.value.notes,
          status: 'reading',
          addedAt: new Date().toISOString(),
          finishedAt: null,
        };
        books.push(book);
        await write(books);
        return book;
      });
    },
    finish(id) {
      return enqueue(async () => {
        const books = await read();
        const book = books.find((item) => item.id === id);
        if (!book) return null;
        if (book.status !== 'finished') {
          book.status = 'finished';
          book.finishedAt = new Date().toISOString();
          await write(books);
        }
        return book;
      });
    },
  };
}
"}

