function escapeHtml(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function page({ title, header, body, savedIn }) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)}</title>
  <style>${css}</style>
</head>
<body>
  <div class="wrap">
    <header>${header}</header>
    <main>${body}</main>
    <footer>Saved in ${escapeHtml(savedIn)} on this computer. No account.</footer>
  </div>
</body>
</html>`;
}

function bookList(books, { showFinish }) {
  if (books.length === 0) {
    return `<p class="empty">${showFinish ? 'Nothing in progress.' : 'None yet.'}</p>`;
  }
  return `<ul class="books">${books.map((book) => bookItem(book, showFinish)).join('')}</ul>`;
}

function bookItem(book, showFinish) {
  const href = `/books/${encodeURIComponent(book.id)}`;
  const finish = showFinish
    ? `<form method="post" action="${escapeHtml(href)}/finish">
        <input type="hidden" name="next" value="home">
        <button type="submit" aria-label="Mark ${escapeHtml(book.title)} finished">Mark finished</button>
      </form>`
    : '';
  return `<li class="book">
    <a class="book-link" href="${escapeHtml(href)}">
      <span class="title">${escapeHtml(book.title)}</span>
      <span class="author">${escapeHtml(book.author)}</span>
    </a>
    ${finish}
  </li>`;
}

export function renderHome(books, options = {}) {
  const errors = options.errors ?? [];
  const form = {
    title: options.form?.title ?? '',
    author: options.form?.author ?? '',
    notes: options.form?.notes ?? '',
  };
  const savedIn = options.savedIn ?? 'books.json';
  const grouped = groupBooks(books);
  const errorList = errors.length
    ? `<ul class="errors" role="alert">${errors.map((error) => `<li>${escapeHtml(error)}</li>`).join('')}</ul>`
    : '';
  const titleInvalid = errors.some((error) => error.startsWith('Title'));
  const authorInvalid = errors.some((error) => error.startsWith('Author'));

  return page({
    title: 'Bookshelf',
    savedIn,
    header: `<p class="eyebrow">Reading list</p>
      <h1>Bookshelf</h1>
      <p class="lede">What you're reading now, and what you've finished.</p>`,
    body: `<section id="reading" aria-labelledby="reading-heading">
        <h2 id="reading-heading">Currently reading <span class="count">${grouped.reading.length}</span></h2>
        ${bookList(grouped.reading, { showFinish: true })}
      </section>
      <section id="finished" aria-labelledby="finished-heading">
        <h2 id="finished-heading">Finished <span class="count">${grouped.finished.length}</span></h2>
        ${bookList(grouped.finished, { showFinish: false })}
      </section>
      <section id="add-book">
        <h2>Add a book</h2>
        ${errorList}
        <form class="add" method="post" action="/books">
          <label>
            <span>Title</span>
            <input name="title" required maxlength="200" value="${escapeHtml(form.title)}" ${titleInvalid ? 'autofocus aria-invalid="true"' : ''}>
          </label>
          <label>
            <span>Author</span>
            <input name="author" required maxlength="200" value="${escapeHtml(form.author)}" ${authorInvalid && !titleInvalid ? 'autofocus aria-invalid="true"' : ''} ${authorInvalid ? 'aria-invalid="true"' : ''}>
          </label>
          <label>
            <span>Notes</span>
            <textarea name="notes" rows="5" maxlength="5000" placeholder="A line you want to remember, or why you picked it up.">${escapeHtml(form.notes)}</textarea>
          </label>
          <button class="primary" type="submit">Add book</button>
        </form>
      </section>`,
  });
}

export function renderBook(book, options = {}) {
  const savedIn = options.savedIn ?? 'books.json';
  const shareUrl = options.shareUrl ?? `/books/${encodeURIComponent(book.id)}`;
  const finished = book.status === 'finished';
  const notes = book.notes
    ? `<p class="notes">${escapeHtml(book.notes)}</p>`
    : '<p class="notes empty">No notes yet.</p>';
  const finish = finished
    ? ''
    : `<form class="actions" method="post" action="/books/${encodeURIComponent(book.id)}/finish">
        <input type="hidden" name="next" value="book">
        <button type="submit">Mark finished</button>
      </form>`;

  return page({
    title: `${book.title} · Bookshelf`,
    savedIn,
    header: `<a class="brand" href="/">Bookshelf</a>`,
    body: `<p class="back"><a href="/">All books</a></p>
      <article>
        <p class="status${finished ? ' finished' : ''}">${finished ? 'Finished' : 'Currently reading'}</p>
        <h1>${escapeHtml(book.title)}</h1>
        <p class="byline"><span class="label">Author</span>${escapeHtml(book.author)}</p>
        <h2 class="notes-heading">Notes</h2>
        ${notes}
        ${finish}
        <section class="share">
          <h2>Share</h2>
          <p>Send this link to open this book directly.</p>
          <p><a href="${escapeHtml(shareUrl)}">${escapeHtml(shareUrl)}</a></p>
        </section>
      </article>`,
  });
}

export function renderNotFound(options = {}) {
  return page({
    title: 'Book not found · Bookshelf',
    savedIn: options.savedIn ?? 'books.json',
    header: `<a class="brand" href="/">Bookshelf</a>`,
    body: `<p class="back"><a href="/">All books</a></p>
      <h1>Book not found</h1>
      <p class="lede">That link doesn't match a book on this shelf.</p>`,
  });
}
"}

{"path":"/workspace/src/server.js","content":"import http from 'node:http';
import { basename } from 'node:path';
import { ValidationError, createStore } from './store.js';
import { renderBook, renderHome, renderNotFound } from './html.js';

const MAX_BODY = 64 * 1024;

function sendHtml(res, status, html) {
  res.writeHead(status, {
    'content-type': 'text/html; charset=utf-8',
    'cache-control': 'no-store',
    'x-content-type-options': 'nosniff',
  });
  res.end(html);
}

function sendText(res, status, text) {
  res.writeHead(status, {
    'content-type': 'text/plain; charset=utf-8',
    'cache-control': 'no-store',
  });
  res.end(text);
}

function redirect(res, location) {
  res.writeHead(303, {
    location,
    'cache-control': 'no-store',
  });
  res.end();
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    req.on('data', (chunk) => {
      size += chunk.length;
      if (size > MAX_BODY) {
        reject(Object.assign(new Error('Payload too large'), { status: 413 }));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function segmentsOf(pathname) {
  return pathname
    .split('/')
    .filter(Boolean)
    .map((part) => {
      try {
        return decodeURIComponent(part);
      } catch {
        return part;
      }
    });
}

function shareUrlFor(req, id) {
  const path = `/books/${encodeURIComponent(id)}`;
  const host = req.headers.host || '';
  if (!/^[A-Za-z0-9.:-]+$/.test(host)) return path;
  const forwarded = req.headers['x-forwarded-proto'];
  const protoHeader = typeof forwarded === 'string' ? forwarded.split(',')[0].trim() : '';
  const proto = protoHeader === 'http' || protoHeader === 'https' ? protoHeader : 'http';
  return `${proto}://${host}${path}`;
}

export function createApp(store) {
  const savedIn = basename(store.filePath || 'books.json');

  return http.createServer((req, res) => {
    route(req, res, store, savedIn).catch((error) => {
      if (error && error.status === 413) {
        if (!res.headersSent) sendText(res, 413, 'Request is too large.');
        else res.end();
        return;
      }
      console.error(error);
      if (!res.headersSent) sendText(res, 500, 'Something went wrong.');
      else res.end();
    });
  });
}

async function route(req, res, store, savedIn) {
  const method = req.method || 'GET';
  let url;
  try {
    url = new URL(req.url || '/', 'http://localhost');
  } catch {
    sendText(res, 400, 'Bad request.');
    return;
  }

  if (url.pathname === '/favicon.ico') {
    res.writeHead(204);
    res.end();
    return;
  }

  if (method === 'GET' && url.pathname.length > 1 && url.pathname.endsWith('/')) {
    redirect(res, url.pathname.slice(0, -1) + url.search);
    return;
  }

  const parts = segmentsOf(url.pathname);

  if (parts.length === 0 && method === 'GET') {
    sendHtml(res, 200, renderHome(await store.list(), { savedIn }));
    return;
  }

  if (parts.length === 1 && parts[0] === 'books' && method === 'POST') {
    const params = new URLSearchParams(await readBody(req));
    const input = {
      title: params.get('title') ?? '',
      author: params.get('author') ?? '',
      notes: params.get('notes') ?? '',
    };
    try {
      await store.add(input);
    } catch (error) {
      if (!(error instanceof ValidationError)) throw error;
      sendHtml(res, 400, renderHome(await store.list(), {
        errors: error.errors,
        form: input,
        savedIn,
      }));
      return;
    }
    redirect(res, '/');
    return;
  }

  if (parts[0] === 'books' && parts.length === 2 && method === 'GET') {
    const book = await store.get(parts[1]);
    if (!book) {
      sendHtml(res, 404, renderNotFound({ savedIn }));
      return;
    }
    sendHtml(res, 200, renderBook(book, {
      savedIn,
      shareUrl: shareUrlFor(req, book.id),
    }));
    return;
  }

  if (parts[0] === 'books' && parts.length === 3 && parts[2] === 'finish') {
    if (method !== 'POST') {
      sendText(res, 405, 'Use the Mark finished button.');
      return;
    }
    const params = new URLSearchParams(await readBody(req));
    const book = await store.finish(parts[1]);
    if (!book) {
      sendHtml(res, 404, renderNotFound({ savedIn }));
      return;
    }
    const next = params.get('next') === 'book'
      ? `/books/${encodeURIComponent(book.id)}`
      : '/';
    redirect(res, next);
    return;
  }

  sendHtml(res, 404, renderNotFound({ savedIn }));
}

function resolvePort(value = process.env.PORT) {
  if (value == null || value === '') return 3000;
  const port = Number(value);
  if (!Number.isInteger(port) || port < 0 || port > 65535) {
    throw new Error(`Invalid PORT: ${value}`);
  }
  return port;
}

export function startServer({
  store = createStore(),
  port = resolvePort(),
  host = process.env.HOST || '127.0.0.1',
} = {}) {
  const server = createApp(store);
  return new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(port, host, () => {
      const address = server.address();
      resolve({
        server,
        store,
        host,
        port: typeof address === 'object' && address ? address.port : port,
      });
    });
  });
}
"}

{"path":"/workspace/server.js","content":"import { fileURLToPath } from 'node:url';
import { createStore, defaultBooksPath } from './src/store.js';
import { startServer } from './src/server.js';

const booksPath = process.env.BOOKS_FILE || defaultBooksPath;
const store = createStore(booksPath);

store
  .init()
  .then(() => startServer({ store }))
  .then(({ host, port }) => {
    console.log(`Bookshelf at http://${host}:${port}`);
    console.log(`Saving books to ${booksPath}`);
  })
  .catch((error) => {
    console.error(error && error.message ? error.message : error);
    process.exit(1);
  });

void fileURLToPath;
"}

{"path":"/workspace/test/store.test.js","content":"import { mkdtemp, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, describe, expect, it } from 'vitest';
import { ValidationError, createStore } from '../src/store.js';

const directories = [];

afterEach(async () => {
  await Promise.all(directories.splice(0).map((dir) => rm(dir, { recursive: true, force: true })));
});

async function tempStore() {
  const dir = await mkdtemp(join(tmpdir(), 'bookshelf-store-'));
  directories.push(dir);
  return createStore(join(dir, 'books.json'));
}

describe('store', () => {
  it('starts empty when the file is missing', async () => {
    const store = await tempStore();
    expect(await store.list()).toEqual([]);
  });

  it('saves a book to the JSON file and reads it back after a new store is opened', async () => {
    const store = await tempStore();
    const added = await store.add({
      title: '  Kindred ',
      author: ' Octavia E. Butler ',
      notes: ' The past is not done. ',
    });

    expect(added.status).toBe('reading');
    expect(added.finishedAt).toBeNull();
    expect(added.title).toBe('Kindred');
    expect(added.author).toBe('Octavia E. Butler');
    expect(added.notes).toBe('The past is not done.');

    const reopened = createStore(store.filePath);
    const books = await reopened.list();
    expect(books).toHaveLength(1);
    expect(books[0]).toMatchObject({
      id: added.id,
      title: 'Kindred',
      author: 'Octavia E. Butler',
      notes: 'The past is not done.',
      status: 'reading',
    });
  });

  it('marks one book finished without dropping the others', async () => {
    const store = await tempStore();
    const first = await store.add({ title: 'Piranesi', author: 'Susanna Clarke', notes: 'House' });
