import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { startServer } from '../src/server.js';
import { createStore } from '../src/store.js';

let dir;
let started;

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'bookshelf-server-'));
  started = await startServer({
    store: createStore(join(dir, 'books.json')),
    port: 0,
    host: '127.0.0.1',
  });
});

afterEach(async () => {
  if (started) {
    await new Promise((resolve, reject) => {
      started.server.close((error) => (error ? reject(error) : resolve()));
    });
  }
  if (dir) await rm(dir, { recursive: true, force: true });
});

function url(path) {
  return `http://127.0.0.1:${started.port}${path}`;
}

function post(path, fields) {
  return fetch(url(path), {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams(fields),
    redirect: 'manual',
  });
}

function section(html, id) {
  const match = html.match(new RegExp(`<section id="${id}">([\\s\\S]*?)</section>`));
  return match ? match[1] : '';
}

describe('server', () => {
  it('shows current books, finished books, and an add form', async () => {
    const response = await fetch(url('/'));
    expect(response.status).toBe(200);
    const html = await response.text();
    expect(html).toContain('Currently reading');
    expect(html).toContain('Finished');
    expect(html).toContain('Add a book');
    expect(html).toContain('name="title"');
    expect(html).toContain('name="author"');
    expect(html).toContain('name="notes"');
    expect(section(html, 'reading')).toContain('Nothing in progress.');
    expect(section(html, 'finished')).toContain('None yet.');
  });

  it('adds a book from the form and keeps it after a restart', async () => {
    const created = await post('/books', {
      title: 'The Left Hand of Darkness',
      author: 'Ursula K. Le Guin',
      notes: 'Winter.',
    });
    expect(created.status).toBe(303);
    expect(created.headers.get('location')).toBe('/');

    const file = JSON.parse(await readFile(join(dir, 'books.json'), 'utf8'));
    expect(file).toHaveLength(1);
    expect(file[0]).toMatchObject({
      title: 'The Left Hand of Darkness',
      author: 'Ursula K. Le Guin',
      notes: 'Winter.',
      status: 'reading',
    });

    await new Promise((resolve, reject) => {
      started.server.close((error) => (error ? reject(error) : resolve()));
    });
    started = await startServer({
      store: createStore(join(dir, 'books.json')),
      port: 0,
      host: '127.0.0.1',
    });

    const html = await (await fetch(url('/'))).text();
    expect(section(html, 'reading')).toContain('The Left Hand of Darkness');
    expect(section(html, 'finished')).not.toContain('The Left Hand of Darkness');
  });

  it('opens a shareable book page with title, author, and notes', async () => {
    const book = await started.store.add({
      title: 'Kindred',
      author: 'Octavia E. Butler',
      notes: 'line one\nline two',
    });

    const response = await fetch(url(`/books/${book.id}`));
    expect(response.status).toBe(200);
    const html = await response.text();
    expect(html).toContain('<h1>Kindred</h1>');
    expect(html).toContain('Octavia E. Butler');
    expect(html).toContain('Author');
    expect(html).toContain('Notes');
    expect(html).toContain('line one\nline two');
    expect(html).toContain(`http://127.0.0.1:${started.port}/books/${book.id}`);
    expect(html).toContain('Currently reading');
  });

  it('escapes book text', async () => {
    const book = await started.store.add({
      title: '<img src=x onerror=alert(1)>',
      author: 'A & B',
      notes: '</textarea><script>alert(1)</script>',
    });
    const html = await (await fetch(url(`/books/${book.id}`))).text();
    expect(html).not.toContain('<script>');
    expect(html).not.toContain('<img');
    expect(html).toContain('&lt;script&gt;');
    expect(html).toContain('A &amp; B');
  });

  it('marks a book finished from the list and from its page', async () => {
    const staying = await started.store.add({ title: 'Circe', author: 'Madeline Miller', notes: '' });
    const moving = await started.store.add({ title: 'Piranesi', author: 'Susanna Clarke', notes: 'Halls.' });

    const fromList = await post(`/books/${moving.id}/finish`, { next: 'home' });
    expect(fromList.status).toBe(303);
    expect(fromList.headers.get('location')).toBe('/');

    let html = await (await fetch(url('/'))).text();
    expect(section(html, 'reading')).toContain('Circe');
    expect(section(html, 'reading')).not.toContain('Piranesi');
    expect(section(html, 'finished')).toContain('Piranesi');
    expect(section(html, 'finished')).not.toContain('Mark finished');

    const detail = await fetch(url(`/books/${moving.id}`));
    const detailHtml = await detail.text();
    expect(detailHtml).toContain('Finished');
    expect(detailHtml).toContain('Halls.');
    expect(detailHtml).not.toContain('Mark finished');

    const other = await post(`/books/${staying.id}/finish`, { next: 'book' });
    expect(other.headers.get('location')).toBe(`/books/${staying.id}`);
    expect(await (await fetch(url(`/books/${staying.id}`))).text()).toContain('Finished');
  });

  it('keeps a rejected form on the page and does not save it', async () => {
    const response = await post('/books', { title: 'Untitled draft', author: '   ', notes: 'hmm' });
    expect(response.status).toBe(400);
    const html = await response.text();
    expect(html).toContain('Author is required.');
    expect(html).toContain('Untitled draft');
    expect(await started.store.list()).toEqual([]);
  });

  it('returns not found for an unknown book and ignores finish links', async () => {
    const missing = await fetch(url('/books/not-a-real-book'));
    expect(missing.status).toBe(404);
    expect(await missing.text()).toContain('Book not found');

    const book = await started.store.add({ title: 'Circe', author: 'Madeline Miller', notes: '' });
    const finishLink = await fetch(url(`/books/${book.id}/finish`));
    expect(finishLink.status).toBe(405);
    expect((await started.store.get(book.id)).status).toBe('reading');
  });

  it('does not overwrite a broken JSON file', async () => {
    await writeFile(join(dir, 'books.json'), '{');
    const response = await fetch(url('/'));
    expect(response.status).toBe(500);
    expect(await readFile(join(dir, 'books.json'), 'utf8')).toBe('{');
  });
});
"}

